const pathIcon={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m15.4 8.6-2 4.8-4.8 2 2-4.8z"/>',book:'<path d="M4 5h6a3 3 0 0 1 3 3v12H7a3 3 0 0 0-3 1zM20 5h-4a3 3 0 0 0-3 3v12h4a3 3 0 0 1 3 1z"/>',chart:'<path d="M3 20h18M7 16V9M12 16V4M17 16v-5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',plus:'<path d="M12 5v14M5 12h14"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.2-1.4l1.8-1.4-2-3.4-2.1.8a8 8 0 0 0-2.4-1.4L13.7 3h-3.4l-.4 2.2a8 8 0 0 0-2.4 1.4l-2.1-.8-2 3.4 1.8 1.4a7 7 0 0 0 0 2.8l-1.8 1.4 2 3.4 2.1-.8a8 8 0 0 0 2.4 1.4l.4 2.2h3.4l.4-2.2a8 8 0 0 0 2.4-1.4l2.1.8 2-3.4-1.8-1.4A7 7 0 0 0 19 12z"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',arrow:'<path d="m15 18-6-6 6-6"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 14v6a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-6"/>',heart:'<path d="M20.8 8.6a5 5 0 0 0-8.8-2.9 5 5 0 0 0-8.8 2.9c-.4 4.1 8.8 10.2 8.8 10.2s9.2-6.1 8.8-10.2z"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',refresh:'<path d="M20 11a8 8 0 1 0-2.2 6.3M20 4v7h-7"/>',camera:'<path d="M4 7h4l2-3h4l2 3h4v13H4z"/><circle cx="12" cy="13" r="4"/>',check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="m9 18 6-6-6-6"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="2"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15"/>',edit:'<path d="m3 17 1 4 4-1L20 8l-4-4z"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>'};
